body:
I tried messing with the TileMapPattern and didn't notice any improvement.. unless i'm missing something here.. 

Even when using get_pattern and set_pattern i still have lag when deleting a tile..  I don't understand why there isn't a more efficient way to modify tiles without the tilemaplayer needing to go over every tile again. Especially considering only a small percent of my world is being rendered in my viewport.. am i just missing something? 

Yesterday i wrote a simple custom tilemap system that uses Texture2D images for individual tile types. 
I'm generated even larger worlds than the worlds i had problems with while using the TileMapLayer.
yet i am able to delete tiles in real time with no performance hit at all. But when i try the same thing with the TIleMapLayer, it freezes up every time a tile is deleted.. Is that because the entire TileMapLayer is being redrawn or scanned over each time a tile is deleted? I don't see why it would need to go over the entire TileMapLayer if only a small percent of the TileMap is being rendered in my viewport..  Sorry if i am asking dumb questions or entirely misunderstand whats going on.


Here is the script i made to attempt to use the TileMapPattern. Is this method the correct usage?


```
extends Node2D

@onready var tilemap_layer = Global.WorldTileLayer
@onready var player = get_parent()
@onready var area: Area2D = $"../TileHandlerRadius"

var rectangle_size_tiles: Vector2i = Vector2i(10, 10) 
var tile_size: Vector2 = Vector2(16, 16) 
var last_player_tile: Vector2i = Vector2i(0, 0) 

func _ready():
	print("TileHandler Player Var:", player)
	print("TileMapLayer:", tilemap_layer)
	print("Area2D:", area)

func _process(_delta):
	var player_tile = tilemap_layer.local_to_map(player.position)

	if player_tile != last_player_tile:
		last_player_tile = player_tile

func _input(event):
	if event is InputEventMouseButton and event.button_index == MOUSE_BUTTON_LEFT and event.is_pressed():
		print("Mouse clicked, calling remove_tile()")
		remove_tile()

func get_tiles_in_rectangle() -> Array[Vector2i]:
	var coords: Array[Vector2i] = []
	var player_tile = tilemap_layer.local_to_map(player.position)

	var half_size = rectangle_size_tiles / 2
	for x in range(-half_size.x, half_size.x + 1):
		for y in range(-half_size.y, half_size.y + 1):
			var tile = player_tile + Vector2i(x, y)
			coords.append(tile)

	return coords

func get_bounding_box_origin(coords: Array[Vector2i]) -> Vector2i:
	if coords.is_empty():
		return Vector2i(0, 0)
	var min_x = coords[0].x
	var min_y = coords[0].y
	for coord in coords:
		min_x = min(min_x, coord.x)
		min_y = min(min_y, coord.y)
	return Vector2i(min_x, min_y)

func remove_tile():
	var mouse_pos = get_global_mouse_position()
	var target_tile = tilemap_layer.local_to_map(mouse_pos)
	print("Mouse Position:", mouse_pos)
	print("Target Tile:", target_tile)

	var player_tile = tilemap_layer.local_to_map(player.position)
	var half_size = rectangle_size_tiles / 2
	var min_tile = player_tile - half_size
	var max_tile = player_tile + half_size
	print("Player Tile:", player_tile)
	print("Min Tile:", min_tile, "Max Tile:", max_tile)
	if target_tile.x < min_tile.x or target_tile.x > max_tile.x or \
	   target_tile.y < min_tile.y or target_tile.y > max_tile.y:
		print("Target tile is outside the Area2D radius!")
		return 

	# Verify a tile exists at the target position
	var source_id = tilemap_layer.get_cell_source_id(target_tile)
	if source_id == -1:
		print("No tile exists at target position!")
		return
	print("Source ID at Target Tile (before):", source_id)

	# Extract a 1x1 pattern for just the target tile
	var tile_coords: Array[Vector2i] = [target_tile]
	print("Tile Coords for Pattern:", tile_coords)
	var pattern = tilemap_layer.get_pattern(tile_coords)
	print("Pattern Extracted:", pattern)

	# set the tile to empty in the pattern
	pattern.set_cell(Vector2i(0, 0), -1, Vector2i(0, 0), 0)
	print("Pattern after set_cell:", pattern)

	# verify pattern is empty at (0, 0)
	var pattern_source_id = pattern.get_cell_source_id(Vector2i(0, 0))
	print("Pattern Source ID at (0, 0):", pattern_source_id)

	# Apply the modified pattern back to the TileMapLayer
	tilemap_layer.set_pattern(target_tile, pattern)
	print("Pattern Applied at:", target_tile)

	# Verify the tile was removed
	source_id = tilemap_layer.get_cell_source_id(target_tile)
	print("Source ID at Target Tile (after):", source_id)

	# Fallback if set_pattern didn't work
	if source_id != -1:
		print("set_pattern failed to clear the tile, falling back to erase_cell")
		tilemap_layer.erase_cell(target_tile)
		source_id = tilemap_layer.get_cell_source_id(target_tile)
		print("Source ID after erase_cell:", source_id)
```
